CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(name text PRIMARY KEY, permissions jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY, name text NOT NULL, username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL REFERENCES roles(name), active boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id text REFERENCES users(id),expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(id text PRIMARY KEY,data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS patients(id text PRIMARY KEY,mrn text UNIQUE NOT NULL,name text NOT NULL,sex text NOT NULL CHECK(sex IN ('male','female','unknown')),birth_at timestamptz NOT NULL,gestation_weeks numeric,birth_weight numeric,mother_name text,guardian_name text,guardian_phone text,twin_label text,allergy_status text DEFAULT 'unknown',version integer DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS beds(id text PRIMARY KEY,name text UNIQUE NOT NULL,room text NOT NULL,status text NOT NULL CHECK(status IN ('available','reserved','occupied','cleaning','maintenance','out_of_service')),care_level text NOT NULL,reason text,version integer DEFAULT 1);
CREATE TABLE IF NOT EXISTS admissions(id text PRIMARY KEY,admission_no text UNIQUE NOT NULL,patient_id text NOT NULL REFERENCES patients(id),admitted_at timestamptz DEFAULT now(),discharged_at timestamptz,status text DEFAULT 'active' CHECK(status IN ('active','discharged')),bed_id text REFERENCES beds(id),care_level text,source text,reason text,diagnosis text,doctor_id text REFERENCES users(id),nurse_id text REFERENCES users(id),summary text,recipient text,discharge_type text,followup_at timestamptz,version integer DEFAULT 1);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_bed ON admissions(bed_id) WHERE status='active' AND bed_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS one_active_admission ON admissions(patient_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS bed_movements(id text PRIMARY KEY,admission_id text REFERENCES admissions(id),from_bed_id text REFERENCES beds(id),to_bed_id text REFERENCES beds(id),reason text,care_level text,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id text PRIMARY KEY,admission_id text NOT NULL REFERENCES admissions(id),type text NOT NULL,name text NOT NULL,dose numeric,unit text,route text,frequency text,instructions text,reference_weight numeric,scheduled_at timestamptz,status text NOT NULL DEFAULT 'draft',created_by text REFERENCES users(id),approved_by text REFERENCES users(id),approved_at timestamptz,reason text,version integer DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS order_versions(id text PRIMARY KEY,order_id text REFERENCES orders(id),data jsonb NOT NULL,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS administrations(id text PRIMARY KEY,order_id text NOT NULL REFERENCES orders(id),scheduled_at timestamptz NOT NULL,actual_at timestamptz NOT NULL,quantity numeric NOT NULL CHECK(quantity>=0),unit text NOT NULL,reason text,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now(),UNIQUE(order_id,scheduled_at));
CREATE TABLE IF NOT EXISTS vitals(id text PRIMARY KEY,admission_id text REFERENCES admissions(id),measured_at timestamptz NOT NULL,temperature numeric,heart_rate numeric,respiratory_rate numeric,spo2 numeric,weight numeric,glucose numeric,intake numeric,output numeric,notes text,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notes(id text PRIMARY KEY,admission_id text REFERENCES admissions(id),text text NOT NULL,kind text,status text NOT NULL,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS labs(id text PRIMARY KEY,admission_id text REFERENCES admissions(id),name text NOT NULL,priority text DEFAULT 'routine',status text DEFAULT 'ordered',result text,unit text,reference_range text,critical boolean DEFAULT false,reason text,created_by text REFERENCES users(id),reviewed_by text REFERENCES users(id),reviewed_at timestamptz,version integer DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS lab_versions(id text PRIMARY KEY,lab_id text REFERENCES labs(id),data jsonb,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS milk(id text PRIMARY KEY,admission_id text REFERENCES admissions(id),quantity numeric NOT NULL CHECK(quantity>0),remaining numeric NOT NULL CHECK(remaining>=0),received_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,location text,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS feedings(id text PRIMARY KEY,admission_id text REFERENCES admissions(id),type text,route text,quantity numeric NOT NULL CHECK(quantity>0),actual_at timestamptz NOT NULL,milk_id text REFERENCES milk(id),notes text,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks(id text PRIMARY KEY,admission_id text REFERENCES admissions(id),order_id text REFERENCES orders(id),title text NOT NULL,due_at timestamptz NOT NULL,assignee_id text REFERENCES users(id),status text DEFAULT 'pending',reason text,version integer DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS handovers(id text PRIMARY KEY,admission_id text REFERENCES admissions(id),summary text NOT NULL,pending text,receiver_id text REFERENCES users(id),sender_id text REFERENCES users(id),acknowledged_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory(id text PRIMARY KEY,name text NOT NULL,unit text NOT NULL,batch text NOT NULL,expires_at date NOT NULL,quantity numeric NOT NULL CHECK(quantity>=0),min_quantity numeric DEFAULT 0,cost numeric NOT NULL CHECK(cost>=0),location text,version integer DEFAULT 1,UNIQUE(name,batch,location));
CREATE TABLE IF NOT EXISTS stock_movements(id text PRIMARY KEY,item_id text REFERENCES inventory(id),type text NOT NULL,quantity numeric NOT NULL CHECK(quantity>0),admission_id text REFERENCES admissions(id),reason text NOT NULL,cost_snapshot numeric,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS prices(id text PRIMARY KEY,name text NOT NULL,category text NOT NULL,price numeric NOT NULL CHECK(price>=0),unit text NOT NULL,valid_from timestamptz NOT NULL,created_by text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS charges(id text PRIMARY KEY,admission_id text REFERENCES admissions(id),price_id text REFERENCES prices(id),name text NOT NULL,quantity numeric NOT NULL CHECK(quantity>0),unit_price numeric NOT NULL CHECK(unit_price>=0),amount numeric NOT NULL CHECK(amount>=0),source text DEFAULT 'manual',actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS cash_closures(id text PRIMARY KEY,closed_at timestamptz DEFAULT now(),actor_id text REFERENCES users(id),reason text NOT NULL,total numeric NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id text PRIMARY KEY,receipt_no text UNIQUE NOT NULL,admission_id text REFERENCES admissions(id),amount numeric NOT NULL CHECK(amount<>0),method text NOT NULL,reference text,original_payment_id text REFERENCES payments(id),closure_id text REFERENCES cash_closures(id),actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS records(id text PRIMARY KEY,kind text NOT NULL,title text NOT NULL,status text NOT NULL,admission_id text REFERENCES admissions(id),data jsonb NOT NULL DEFAULT '{}',version integer DEFAULT 1,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS record_kind ON records(kind);
CREATE TABLE IF NOT EXISTS idempotency(key text PRIMARY KEY,user_id text REFERENCES users(id),route text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id text PRIMARY KEY,actor_id text REFERENCES users(id),action text NOT NULL,entity text NOT NULL,entity_id text,patient_id text REFERENCES patients(id),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz DEFAULT now());
INSERT INTO schema_migrations(version) VALUES (1) ON CONFLICT DO NOTHING;
